function customModuleGroups(){const v=get('customModuleGroups',[]);return Array.isArray(v)?v.filter(g=>g&&typeof g.id==='string'&&typeof g.title==='string'):[]}
function allModuleGroups(){const icons=get('moduleCategoryIcons',{});return [...groups,...customModuleGroups()].map(g=>({...g,icon:Object.prototype.hasOwnProperty.call(icons,g.id)?icons[g.id]:g.icon}))}
function orderedGroups(){const gs=allModuleGroups(),ids=get('moduleCategoryOrder',[]);return gs.sort((a,b)=>{const ia=ids.indexOf(a.id),ib=ids.indexOf(b.id);return (ia<0?gs.indexOf(a)+ids.length:ia)-(ib<0?gs.indexOf(b)+ids.length:ib)})}
function moduleGroupAssignments(){const v=get('moduleGroupAssignments',{});return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}
function archivedModuleIds(){const v=get('archivedModuleIds',[]);return Array.isArray(v)?v:[]}
function toolsForGroup(g){const assigned=moduleGroupAssignments(),archived=archivedModuleIds(),gs=allModuleGroups();return defs.filter(d=>{const original=groups.find(x=>x.tools.includes(d[0]));return original&&!archived.includes(d[0])&&(gs.some(x=>x.id===assigned[d[0]])?assigned[d[0]]:original.id)===g.id}).map(d=>d[0])}
let moduleAssignmentDraft=null;
function renderModuleAssignmentSettings(){
 const el=document.getElementById('module-assignment-settings-list');if(!el)return;
 if(!moduleAssignmentDraft)moduleAssignmentDraft={...moduleGroupAssignments(),...Object.fromEntries(archivedModuleIds().map(id=>[id,'__archive']))};
 const gs=allModuleGroups(),archived=archivedModuleIds();
 el.innerHTML=defs.filter(d=>groups.some(g=>g.tools.includes(d[0]))).sort((a,b)=>String(a[2]).localeCompare(String(b[2]),'fr',{sensitivity:'base'})).map(d=>{
 const original=groups.find(g=>g.tools.includes(d[0]));
 const chosen=moduleAssignmentDraft[d[0]]==='__archive'?'__archive':gs.some(g=>g.id===moduleAssignmentDraft[d[0]])?moduleAssignmentDraft[d[0]]:archived.includes(d[0])?'__archive':original.id;
 const category=chosen==='__archive'?'Archivé':gs.find(g=>g.id===chosen)?.title||'—';
 return `<div class="nx-assign-line"><span class="nx-assign-name" title="${esc(d[2])}">${esc(d[2])}</span><span class="nx-assign-category" title="${esc(category)}">${esc(category)}</span><button type="button" class="nx-assign-pencil" aria-label="Modifier ${esc(d[2])}" onclick="nxEditModule('${d[0]}')">✎</button></div>`
 }).join('');
 const count=archived.length,note=document.getElementById('nexo-archive-count');if(note)note.textContent=count?`${count} module(s) archivé(s) — sélectionne une catégorie pour les réactiver.`:'Aucun module archivé.';
}
function setModuleAssignmentDraft(id,groupId){if(!moduleAssignmentDraft||!(groupId==='__archive'||allModuleGroups().some(g=>g.id===groupId)))return;moduleAssignmentDraft[id]=groupId}
function saveModuleAssignments(){if(!moduleAssignmentDraft)return;const assigned={...moduleGroupAssignments()},archived=new Set(archivedModuleIds());for(const [id,g] of Object.entries(moduleAssignmentDraft)){if(g==='__archive'){archived.add(id)}else{assigned[id]=g;archived.delete(id)}}put('moduleGroupAssignments',assigned);put('archivedModuleIds',[...archived]);moduleAssignmentDraft=null;gen2Modules(false);toast('Classement et archives enregistrés')}
function resetModuleAssignments(){moduleAssignmentDraft={};for(const d of defs){const g=groups.find(x=>x.tools.includes(d[0]));if(g)moduleAssignmentDraft[d[0]]=g.id}renderModuleAssignmentSettings()}
function createModuleCategory(){const input=document.getElementById('nexo-new-category-name');const title=(input?.value||'').trim();if(!title)return toast('Saisis un nom de catégorie');if(title.length>45)return toast('Nom trop long (45 caractères max)');if(allModuleGroups().some(g=>g.title.toLocaleLowerCase('fr')===title.toLocaleLowerCase('fr')))return toast('Cette catégorie existe déjà');const icon=document.getElementById('nexo-new-category-icon')?.value||'▦';const id='custom-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);put('customModuleGroups',[...customModuleGroups(),{id,title,icon,desc:'Catégorie personnalisée',tools:[],tone:'teal'}]);if(!moduleCategoryDraft)moduleCategoryDraft=orderedGroups().map(g=>g.id);moduleCategoryDraft.push(id);renderModuleCategorySettings();renderModuleAssignmentSettings();input.value='';toast('Catégorie créée')}
function deleteModuleCategory(id){const g=customModuleGroups().find(g=>g.id===id);if(!g)return;if(!confirm(`Supprimer la catégorie « ${g.title} » ? Ses modules seront replacés dans leur catégorie d’origine.`))return;put('customModuleGroups',customModuleGroups().filter(g=>g.id!==id));const assigned={...moduleGroupAssignments()};for(const [k,v] of Object.entries(assigned))if(v===id)delete assigned[k];put('moduleGroupAssignments',assigned);if(moduleAssignmentDraft)for(const [k,v] of Object.entries(moduleAssignmentDraft))if(v===id)delete moduleAssignmentDraft[k];moduleCategoryDraft=(moduleCategoryDraft||[]).filter(x=>x!==id);put('moduleCategoryOrder',orderedGroups().map(g=>g.id));renderModuleCategorySettings();renderModuleAssignmentSettings();toast('Catégorie supprimée')}


