function nxEditModule(id){
 const d=defs.find(x=>x[0]===id);if(!d)return;
 const gs=allModuleGroups(),original=groups.find(g=>g.tools.includes(id));
 const chosen=moduleAssignmentDraft?.[id]||moduleGroupAssignments()[id]||original?.id;
 nxClosePicker();document.getElementById('nx-module-edit-overlay')?.remove();
 const overlay=document.createElement('div');overlay.id='nx-module-edit-overlay';
 overlay.innerHTML=`<div class="nx-emoji-panel" role="dialog" aria-modal="true"><div class="nx-emoji-head"><strong>${esc(d[2])}</strong><button type="button" class="btn" id="nx-edit-close">Fermer</button></div><label>Catégorie<select class="field" id="nx-edit-category">${gs.map(g=>`<option value="${g.id}" ${chosen===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}<option value="__archive" ${chosen==='__archive'?'selected':''}>Archivé</option></select></label><p>Icône du module</p><div class="nx-emoji-grid">${nxEmojiChoices.map((x,i)=>`<button type="button" class="nx-emoji-choice" data-idx="${i}">${x}</button>`).join('')}</div><div class="nx-edit-actions"><button type="button" class="btn" id="nx-reset-module-icon">Icône d’origine</button><button type="button" class="btn primary" id="nx-edit-save">Enregistrer</button></div></div>`;
 document.body.appendChild(overlay);
 let selectedIcon=nxModuleIcon(id,d[1]);
 const selectIcon=v=>{selectedIcon=v;overlay.querySelectorAll('.nx-emoji-choice').forEach(b=>b.classList.toggle('nx-selected',nxEmojiChoices[Number(b.dataset.idx)]===v))};
 overlay.querySelectorAll('[data-idx]').forEach(b=>b.onclick=()=>selectIcon(nxEmojiChoices[Number(b.dataset.idx)]));selectIcon(selectedIcon);
 overlay.querySelector('#nx-reset-module-icon').onclick=()=>selectIcon(d[1]);
 overlay.querySelector('#nx-edit-close').onclick=()=>overlay.remove();
 overlay.onclick=e=>{if(e.target===overlay)overlay.remove()};
 overlay.querySelector('#nx-edit-save').onclick=()=>{
  const cat=overlay.querySelector('#nx-edit-category').value;
  setModuleAssignmentDraft(id,cat);
  const icons=get('nxModuleIcons',{});if(selectedIcon===d[1])delete icons[id];else icons[id]=selectedIcon;put('nxModuleIcons',icons);
  // Category change is saved with the existing "Enregistrer le classement" action.
  overlay.remove();renderModuleAssignmentSettings();toast('Icône enregistrée. Enregistre le classement pour valider la catégorie.');
 };
}
