function deleteExpense(id){if(!confirm('Supprimer cette dépense ?'))return;put('expenses',get('expenses',[]).filter(x=>x.id!==id));drawExpenses()}
function clearExpenses(){const all=get('expenses',[]),filter=$('#expFilter')?.value||'all',period=expensePeriodLabel();const selected=all.filter(x=>(filter==='all'||x.category===filter)&&expensePeriodMatch(x));if(!selected.length)return toast('Aucune dépense affichée à supprimer');if(!confirm(`Supprimer définitivement les ${selected.length} dépenses affichées (${period}${filter==='all'?'':', '+filter}) ? Les autres dépenses seront conservées.`))return;const ids=new Set(selected.map(x=>x.id));put('expenses',all.filter(x=>!ids.has(x.id)));drawExpenses();toast(`${selected.length} dépenses affichées supprimées`)}
function exportExpensesExcel(){const rows=get('expenses',[]);if(!rows.length)return toast('Aucune dépense à exporter');const table=[['Date','Catégorie','Description','Montant (EUR)'],...rows.map(x=>[x.date||'',x.category||'',x.desc||'',Number(x.amount)||0])];const enc=new TextEncoder();const xmlEsc=x=>String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;');const sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>'+table.map((r,i)=>'<row r="'+(i+1)+'">'+r.map((v,j)=>{const col=String.fromCharCode(65+j),ref=col+(i+1);return typeof v==='number'&&i>0?`<c r="${ref}"><v>${v}</v></c>`:`<c r="${ref}" t="inlineStr"><is><t>${xmlEsc(v)}</t></is></c>`}).join('')+'</row>').join('')+'</sheetData></worksheet>';const files=[['[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'],['_rels/.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'],['xl/workbook.xml','<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Dépenses" sheetId="1" r:id="rId1"/></sheets></workbook>'],['xl/_rels/workbook.xml.rels','<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'],['xl/worksheets/sheet1.xml',sheet]];const bytes=zipStored(files.map(([n,v])=>[n,enc.encode(v)]));const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const a=document.createElement('a');a.href=url;a.download='Digital-Toolbox-depenses-'+new Date().toISOString().slice(0,10)+'.xlsx';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Export Excel préparé')}
function zipStored(files){const parts=[],directory=[];let offset=0;const u16=n=>[n&255,n>>>8&255],u32=n=>[n&255,n>>>8&255,n>>>16&255,n>>>24&255];function crc(data){let c=0xffffffff;for(const b of data){c^=b;for(let i=0;i<8;i++)c=(c>>>1)^((c&1)?0xedb88320:0)}return(c^0xffffffff)>>>0}for(const [name,data] of files){const n=new TextEncoder().encode(name),sum=crc(data),head=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(sum),...u32(data.length),...u32(data.length),...u16(n.length),...u16(0),...n]);parts.push(head,data);directory.push(new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x800),...u16(0),...u16(0),...u16(0),...u32(sum),...u32(data.length),...u32(data.length),...u16(n.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...n]));offset+=head.length+data.length}const dirSize=directory.reduce((s,x)=>s+x.length,0),end=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(files.length),...u16(files.length),...u32(dirSize),...u32(offset),...u16(0)]);return new Blob([...parts,...directory,end],{type:'application/zip'})}
