'RECHERCHEV':{scenario:'Cherche le code en E2 dans la première colonne de A2:C20 et renvoie la valeur de la 3e colonne.',args:['Valeur recherchée','Tableau de recherche','Numéro de colonne à renvoyer','Correspondance exacte (FAUX) ou approximative (VRAI)']},
