function splitExcelArgs(s){let a=[],cur='',depth=0,quote=false;for(let i=0;i<s.length;i++){let c=s[i];if(c==='"'){if(quote&&s[i+1]==='"'){cur+='""';i++;continue}quote=!quote}if(!quote&&c==='(')depth++;if(!quote&&c===')')depth--;if(!quote&&c===';'&&depth===0){a.push(cur.trim());cur='';continue}cur+=c}if(cur.trim())a.push(cur.trim());return a}
function excelParts(formula){let match=formula.match(/^=([^()]+)\((.*)\)$/);if(!match)return {name:'',args:[],tail:''};let body=match[2],level=0,quote=false,stop=-1;for(let i=0;i<body.length;i++){let c=body[i];if(c==='"')quote=!quote;if(!quote&&c==='(')level++;if(!quote&&c===')'&&level===0){stop=i;break}if(!quote&&c===')')level--}return {name:match[1],args:splitExcelArgs(body),tail:''}}
function excelArgumentLabel(value,i){if(/^\"/.test(value))return 'Texte ou critère';if(/^[A-Z]+\d+:[A-Z]+\d+$/i.test(value))return 'Plage de cellules';if(/^\$?[A-Z]+\$?\d+$/i.test(value))return 'Référence de cellule';if(/^[\d.,%-]+$/.test(value))return 'Nombre ou paramètre';if(/^[A-Z]+\(/i.test(value))return 'Expression ou fonction imbriquée';return 'Argument '+(i+1)}
function excelDetail(i){let x=excelData[i],guide=excelGuides[x[1]]||{},parsed=excelParts(x[3]),labels=parsed.args.map((a,j)=>(guide.args||[])[j]||excelArgumentLabel(a,j));let fields=parsed.args.map((a,j)=>`<label for="excelField-${i}-${j}">${j+1}. ${esc(labels[j])}</label><input id="excelField-${i}-${j}" data-arg="${j}" value="${esc(a)}" spellcheck="false" autocapitalize="off">`).join('');return `<details class="excel-detail"><summary>📖 Explication, arguments et exemple</summary><h4>À quoi sert cette formule ?</h4><p>${esc(x[2])}</p><h4>Comprendre les arguments</h4>${parsed.args.length?parsed.args.map((a,j)=>`<div class="excel-arg"><strong>${j+1}. ${esc(labels[j])}</strong><br><code>${esc(a)}</code></div>`).join(''):'<p class="excel-note">Cette fonction ne nécessite aucun argument.</p>'}<h4>Exemple concret</h4><div class="excel-scenario">${esc(guide.scenario||('Exemple prêt à adapter : '+x[3]+' — '+x[2]+' Remplace les références de cellules par celles de ton fichier.'))}</div><div class="excel-builder"><strong>🛠️ Construire ma formule</strong><p class="excel-note">Modifie les arguments ci-dessous puis copie la formule obtenue.</p>${fields}<div class="excel-result" id="excelBuilt-${i}">${esc(x[3])}</div><button class="btn" type="button" data-buildcopy="${i}">⧉ Copier ma formule</button></div><p class="excel-note">Les arguments et résultats dépendent de tes données. Vérifie la formule dans ta version d’Excel.</p></details>`}
function excelBuild(i){let card=document.querySelector(`[data-excel-index="${i}"]`);if(!card)return;let args=[...card.querySelectorAll('[data-arg]')].map(n=>n.value);let x=excelData[i],name=x[1],formula=args.length?'='+name+'('+args.join(';')+')':x[3];card.querySelector('#excelBuilt-'+i).textContent=formula;return formula}
function drawExcel(){let q=excelNormalize(excelQuery.trim());let rows=excelData.map((x,i)=>({x,i})).filter(({x})=>(excelCategory==='Toutes'||x[0]===excelCategory)&&(!q||excelNormalize(x.join(' ')).includes(q)));$('#excelFilters').innerHTML=excelCategories.map((c,i)=>`<button type="button" class="${c===excelCategory?'selected':''}" onclick="excelSelectCategory(excelCategories[${i}])">${esc(c)}</button>`).join('');$('#excelCount').textContent=`${rows.length} formule${rows.length>1?'s':''} trouvée${rows.length>1?'s':''} · ${excelData.length} dans le répertoire`;$('#excelResults').innerHTML=rows.map(({x,i})=>`<article class="excel-card" data-excel-index="${i}"><div class="excel-top"><span class="excel-name">${esc(x[1])}</span><span class="excel-cat">${esc(x[0])}</span></div><p>${esc(x[2])}</p><code class="excel-code">${esc(x[3])}</code><button class="btn" type="button" data-formula="${esc(x[3])}">⧉ Copier la formule</button>${excelDetail(i)}</article>`).join('')||'<div class="excel-empty">Aucune formule trouvée. Essaie un autre mot-clé.</div>';$('#excelResults').querySelectorAll('[data-formula]').forEach(b=>b.addEventListener('click',()=>copyText(b.dataset.formula)));$('#excelResults').querySelectorAll('[data-excel-index]').forEach(card=>{let i=Number(card.dataset.excelIndex);card.querySelectorAll('[data-arg]').forEach(inp=>inp.addEventListener('input',()=>excelBuild(i)));card.querySelector('[data-buildcopy]').addEventListener('click',()=>copyText(excelBuild(i)))})}


