const daxCategories=['Toutes',...new Set(daxData.map(x=>x[0]))];let daxCategory='Toutes',daxQuery='';
function dax(){daxCategory='Toutes';daxQuery='';content(`<section class="dax-hero"><div class="dax-mark"><svg class="brand-pbi" viewBox="0 0 40 40" aria-hidden="true"><rect x="4" y="20" width="6" height="15" rx="2" fill="#E4A900"/><rect x="12" y="13" width="7" height="22" rx="2" fill="#F2C811"/><rect x="21" y="5" width="7" height="30" rx="2" fill="#F2C811"/><rect x="30" y="12" width="6" height="23" rx="2" fill="#D2A800"/></svg></div><h2>Formules DAX</h2><p>Power BI · ${daxData.length} fonctions et modèles · Exemples concrets et constructeur interactif</p></section><input class="search dax-search" id="daxSearch" type="search" placeholder="⌕  Rechercher : CALCULATE, dates, filtre…" aria-label="Rechercher une formule DAX" autocomplete="off"><div class="dax-filter" id="daxFilters"></div><div class="dax-count" id="daxCount"></div><div id="daxResults"></div><p class="dax-note">Bibliothèque pratique, non exhaustive. DAX utilise les noms de fonctions anglais. Les exemples utilisent des virgules comme séparateurs ; selon les paramètres régionaux de Power BI, il peut falloir les remplacer par des points-virgules. Les tables et mesures sont fictives : adapte-les à ton modèle. Les fonctions peuvent nécessiter un contexte de ligne, de filtre ou une table de dates appropriée.</p>`);$('#daxSearch').addEventListener('input',e=>{daxQuery=e.target.value;drawDax()});drawDax()}
function daxSelectCategory(cat){daxCategory=cat;drawDax()}
function daxSplitArgs(body){let a=[],cur='',depth=0,quote=false;for(let i=0;i<body.length;i++){const c=body[i];if(c==='"'){if(quote&&body[i+1]==='"'){cur+='""';i++;continue}quote=!quote}if(!quote&&c==='(')depth++;if(!quote&&c===')')depth--;if(!quote&&c===','&&depth===0){a.push(cur.trim());cur='';continue}cur+=c}if(cur.trim())a.push(cur.trim());return a}
function daxParts(formula){const m=formula.match(/^([A-Za-z][A-Za-z0-9.]*)\((.*)\)$/s);return m?{name:m[1],args:daxSplitArgs(m[2])}:{name:'',args:[]}}
function daxDetail(i){const x=daxData[i],parts=daxParts(x[3]),labels=x[5];let fields=parts.args.map((a,j)=>`<label for="daxField-${i}-${j}">${j+1}. ${esc(labels[j]||'Argument '+(j+1))}</label><input id="daxField-${i}-${j}" data-daxarg="${j}" value="${esc(a)}" spellcheck="false" autocapitalize="off">`).join('');return `<details class="dax-detail"><summary>📖 Explication, arguments et exemple</summary><h4>À quoi sert cette fonction ?</h4><p>${esc(x[2])}</p><h4>Arguments</h4>${parts.args.length?parts.args.map((a,j)=>`<div class="dax-arg"><strong>${j+1}. ${esc(labels[j]||'Argument '+(j+1))}</strong><div><code>${esc(a)}</code></div></div>`).join(''):'<p class="dax-note">Cette fonction ne prend aucun argument.</p>'}<h4>Exemple concret</h4><div class="dax-scenario">${esc(x[4])}</div><div class="dax-builder"><strong>🛠️ Construire ma formule</strong><p class="dax-note">Modifie les arguments ci-dessous. Le constructeur assemble la syntaxe mais ne valide pas ton modèle Power BI.</p>${fields}<div class="dax-result" id="daxBuilt-${i}">${esc(x[3])}</div><button class="btn" type="button" data-daxcopy="${i}">⧉ Copier ma formule</button></div></details>`}
function daxBuild(i){const card=document.querySelector(`[data-dax-index="${i}"]`);if(!card)return '';const x=daxData[i],p=daxParts(x[3]);const args=[...card.querySelectorAll('[data-daxarg]')].map(n=>n.value);const result=p.name?p.name+'('+args.join(', ')+')':x[3];card.querySelector('#daxBuilt-'+i).textContent=result;return result}
function drawDax(){const q=excelNormalize(daxQuery.trim());const matches=daxData.map((x,i)=>({x,i})).filter(({x})=>(daxCategory==='Toutes'||x[0]===daxCategory)&&(!q||excelNormalize(x.slice(0,5).join(' ')).includes(q)));$('#daxFilters').innerHTML=daxCategories.map((c,i)=>`<button type="button" class="${c===daxCategory?'selected':''}" onclick="daxSelectCategory(daxCategories[${i}])">${esc(c)}</button>`).join('');$('#daxCount').textContent=`${matches.length} résultat${matches.length>1?'s':''} · ${daxData.length} entrées dans le répertoire`;$('#daxResults').innerHTML=matches.map(({x,i})=>`<article class="dax-card" data-dax-index="${i}"><div class="excel-top"><strong class="dax-name">${esc(x[1])}</strong><span class="dax-cat">${esc(x[0])}</span></div><p>${esc(x[2])}</p><code class="dax-code">${esc(x[3])}</code><button class="btn" type="button" data-daxformula="${esc(x[3])}">⧉ Copier l’exemple</button>${daxDetail(i)}</article>`).join('')||'<p class="dax-note">Aucun résultat. Essaie un autre mot-clé.</p>';$('#daxResults').querySelectorAll('[data-daxformula]').forEach(b=>b.addEventListener('click',()=>copyText(b.dataset.daxformula)));$('#daxResults').querySelectorAll('[data-dax-index]').forEach(card=>{const i=Number(card.dataset.daxIndex);card.querySelectorAll('[data-daxarg]').forEach(inp=>inp.addEventListener('input',()=>daxBuild(i)));card.querySelector('[data-daxcopy]').addEventListener('click',()=>copyText(daxBuild(i)))})}



// V10 travel planner: data stays on this device; explicit JSON backup/restore.
let travelId=null,travelTab='planning',travelDay=0;

// Balades moto : données locales, carte OSM, routage routier OSRM public (best effort).
let motoMap=null,motoLayer=null,motoPins=[],motoRoute=null,motoRequest=0,motoSelected=null;
const motoSaved=()=>get('moto_rides_v1',[]);
function motoId(){return crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random()}
function moto(){motoSelected=null;motoHome()}

/* Roadtrip Moto GPS v2.8.34: isolated local tracker, no change to existing trip planner. */
let motoGPSWatch=null,motoGPSMap=null,motoGPSMarker=null,motoGPSLine=null,motoGPSPoints=[],motoGPSStartedAt=0,motoGPSLastSpeed=0,motoGPSAngle=0,motoGPSLeft=0,motoGPSRight=0,motoGPSZero=null,motoGPSMotion=null,motoGPSLastFix=null;
let motoGPSRouteLine=null,motoGPSDestinationMarker=null,motoGPSCurrentDestination=null;
/* Camera navigation is independent of ride recording. */
let motoGPSNavWatch=null,motoGPSNavMode='follow',motoGPSNavHeading=null,motoGPSNavFix=null,motoGPSNavManualZoom=false,motoGPSNavInternal=false,motoGPSRoutePoints=[],motoGPSStableAngle=null,motoGPSStableCount=0;
function motoGPSBearing(a,b){const r=Math.PI/180,dl=(b.lng-a.lng)*r,y=Math.sin(dl)*Math.cos(b.lat*r),x=Math.cos(a.lat*r)*Math.sin(b.lat*r)-Math.sin(a.lat*r)*Math.cos(b.lat*r)*Math.cos(dl);return (Math.atan2(y,x)/r+360)%360}
function motoGPSNavButtons(){const n=document.getElementById('moto-gps-north'),r=document.getElementById('moto-gps-recenter');if(n){n.textContent=motoGPSNavMode==='north'?'↗ Suivi':'N ↑ Nord';n.setAttribute('aria-pressed',String(motoGPSNavMode==='north'))}if(r)r.hidden=motoGPSNavMode==='follow'&&!motoGPSNavManualZoom}
function motoGPSNavNorth(){motoGPSNavMode=motoGPSNavMode==='north'?'follow':'north';motoGPSNavManualZoom=false;motoGPSNavButtons();motoGPSNavRender(true)}
function motoGPSNavRecenter(){motoGPSNavMode='follow';motoGPSNavManualZoom=false;motoGPSNavButtons();motoGPSNavRender(true)}
function motoGPSNavTurnDistance(fix){if(motoGPSRoutePoints.length<3)return Infinity;let nearest=0,closest=Infinity;for(let i=0;i<motoGPSRoutePoints.length;i++){const p=motoGPSRoutePoints[i],d=motoDistance([fix.lat,fix.lng],p);if(d<closest){closest=d;nearest=i}}if(closest>.12)return Infinity;let traveled=0,prev=motoGPSRoutePoints[nearest];for(let i=nearest+1;i<motoGPSRoutePoints.length-1;i++){const next=motoGPSRoutePoints[i];traveled+=motoDistance(prev,next)*1000;prev=next;if(traveled>1300)break;const after=motoGPSRoutePoints[Math.min(i+2,motoGPSRoutePoints.length-1)];const before=motoGPSRoutePoints[Math.max(nearest,i-2)];let angle=Math.abs(((motoGPSBearing({lat:before[0],lng:before[1]},{lat:next[0],lng:next[1]})-motoGPSBearing({lat:next[0],lng:next[1]},{lat:after[0],lng:after[1]})+540)%360)-180);if(angle>40&&traveled>15)return traveled}return Infinity}
function motoGPSNavZoom(fix){const speed=fix.speed||0;let z=speed<8?17:speed<30?16.5:speed<70?15.8:speed<110?15:14.4;const turn=motoGPSNavTurnDistance(fix);if(turn<180)z=Math.max(z,17);else if(turn<450)z=Math.max(z,16.5);return z}
function motoGPSNavRender(immediate=false){
 const map=motoGPSMap,fix=motoGPSNavFix;
 if(!map||!fix||motoGPSNavMode==='free')return;
 const pane=map.getPane('mapPane');if(!pane)return;
 const angle=motoGPSNavMode==='north'?0:(motoGPSNavHeading??0);
 // Keep Leaflet's internal transform untouched; rotation only (no scale) avoids
 // pushing the position marker below the screen when recentering.
 pane.style.rotate=(-angle)+'deg';pane.style.scale='1';
 pane.style.transformOrigin='50% 50%';
 pane.style.transition=immediate?'none':'rotate .65s ease-out';
 const zoom=motoGPSNavManualZoom?map.getZoom():motoGPSNavZoom(fix);
 const size=map.getSize();
 // Position the motorcycle near 63% of screen height, clear of telemetry.
 const offset=Math.min(size.y*.13,Math.max(0,size.y*.74-205));
 const rad=angle*Math.PI/180;
 const pt=map.project([fix.lat,fix.lng],zoom);
 const center=L.point(pt.x+offset*Math.sin(rad),pt.y-offset*Math.cos(rad));
 motoGPSNavInternal=true;
 map.setView(map.unproject(center,zoom),zoom,{animate:false});
 motoGPSNavInternal=false;
}
function motoGPSNavPosition(p){if(!motoGPSMap||!document.getElementById('moto-gps-map'))return;const c=p.coords;if(c.accuracy>100)return;const fix={lat:c.latitude,lng:c.longitude,speed:Number.isFinite(c.speed)&&c.speed>=0?c.speed*3.6:0};const prev=motoGPSNavFix;motoGPSNavFix=fix;
 let heading=Number.isFinite(c.heading)&&c.heading>=0?c.heading:null;if(heading===null&&prev&&fix.speed>6&&motoDistance([prev.lat,prev.lng],[fix.lat,fix.lng])>.008)heading=motoGPSBearing(prev,fix);
 if(heading!==null&&fix.speed>5){if(motoGPSNavHeading===null)motoGPSNavHeading=heading;else{const delta=((heading-motoGPSNavHeading+540)%360)-180;motoGPSNavHeading=(motoGPSNavHeading+Math.max(-35,Math.min(35,delta))*.35+360)%360}}
 const ll=[fix.lat,fix.lng];if(!motoGPSMarker)motoGPSMarker=L.circleMarker(ll,{radius:9,color:'#fff',weight:3,fillColor:'#278aff',fillOpacity:1}).addTo(motoGPSMap);else motoGPSMarker.setLatLng(ll);
 if(motoGPSWatch===null){motoGPSLastSpeed=fix.speed;motoGPSUpdate()}motoGPSNavRender()}
function motoGPSNavStart(){if(!navigator.geolocation)return; if(motoGPSNavWatch!==null)navigator.geolocation.clearWatch(motoGPSNavWatch);motoGPSNavWatch=navigator.geolocation.watchPosition(motoGPSNavPosition,()=>{}, {enableHighAccuracy:true,maximumAge:1000,timeout:15000})}
function motoGPSNavStop(){if(motoGPSNavWatch!==null)navigator.geolocation.clearWatch(motoGPSNavWatch);motoGPSNavWatch=null;motoGPSNavFix=null;motoGPSNavHeading=null;motoGPSNavManualZoom=false;motoGPSRoutePoints=[];motoGPSNavMode='follow'}
function motoGPSOpen(){
 document.body.classList.add('moto-gps-fullscreen');
 setHead('Roadtrip Moto','GPS et télémétrie · version test');
 content(`<div class="moto-gps-screen"><button class="moto-gps-exit" onclick="motoGPSLeave()">← Retour</button><div class="moto-gps-shell"><div id="moto-gps-map" class="moto-gps-map">Chargement de la carte…</div><div class="moto-gps-search"><div class="moto-gps-search-row"><input id="moto-gps-destination" type="search" placeholder="Où veux-tu aller ?" aria-label="Adresse de destination" onkeydown="if(event.key==='Enter')motoGPSFindDestination()"><button onclick="motoGPSFindDestination()" id="moto-gps-find">Chercher</button></div><div id="moto-gps-search-results" class="moto-gps-search-results" hidden></div><div id="moto-gps-route-summary" class="moto-gps-route-summary" hidden></div></div><div class="moto-gps-nav-controls"><button id="moto-gps-north" onclick="motoGPSNavNorth()" aria-label="Basculer orientation Nord">N ↑ Nord</button><button id="moto-gps-recenter" onclick="motoGPSNavRecenter()" aria-label="Recentrer sur la moto" hidden>◎ Recentrer</button></div><div class="moto-gps-panel"><div class="moto-gps-speed"><button class="moto-gps-lean" onclick="motoGPSCalibrate()" title="Toucher pour recalibrer"><small>Inclinaison ↻</small><strong id="moto-gps-angle">—</strong><span id="moto-gps-side">Capteur non activé</span></button><div><small>Vitesse GPS</small><strong id="moto-gps-speed">0</strong><small>km/h</small></div><div><small>Limitation</small><span class="moto-gps-limit" id="moto-gps-limit">—</span><small>Non disponible</small></div></div><div class="moto-gps-stats"><span id="moto-gps-distance">0,00 km</span><span id="moto-gps-duration">00:00</span><span id="moto-gps-max">Max 0 km/h</span></div><div class="moto-gps-actions"><button class="btn primary" id="moto-gps-start" onclick="motoGPSStart()">● Démarrer</button><button class="btn danger" id="moto-gps-stop" onclick="motoGPSStop()" disabled>■ Terminer et enregistrer</button></div><p class="small moto-gps-help">GPS et capteurs indicatifs. Gardez l'écran actif : le suivi en arrière-plan n'est pas garanti sur iPhone. Les limitations de vitesse et le guidage vocal ne sont pas disponibles dans cette première version. Ne manipulez pas l'écran en roulant.</p></div></div>`);
 motoGPSInitMap();
}
async function motoGPSInitMap(){try{await motoLoadLeaflet();if(!document.getElementById('moto-gps-map'))return;if(motoGPSMap){motoGPSMap.remove();motoGPSMap=null}motoGPSMap=L.map('moto-gps-map',{zoomControl:false,zoomSnap:0.1,zoomDelta:0.5}).setView([48.85,2.35],12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19,subdomains:[]}).addTo(motoGPSMap);motoGPSLine=L.polyline([],{color:'#2589ff',weight:6}).addTo(motoGPSMap);motoGPSMap.on('dragstart',()=>{if(!motoGPSNavInternal){motoGPSNavMode='free';motoGPSNavButtons()}});motoGPSMap.on('zoomstart',()=>{if(!motoGPSNavInternal){motoGPSNavManualZoom=true;motoGPSNavMode='free';motoGPSNavButtons()}});motoGPSNavButtons();motoGPSNavStart();setTimeout(()=>motoGPSMap?.invalidateSize(),200)}catch{let e=document.getElementById('moto-gps-map');if(e)e.textContent='Carte indisponible. Connexion Internet nécessaire.'}}

async function motoGPSFindDestination(){
 const input=document.getElementById('moto-gps-destination'),results=document.getElementById('moto-gps-search-results');
 if(!input||!results)return;const q=input.value.trim();if(q.length<3){toast('Saisissez au moins 3 caractères');return}
 results.hidden=false;results.textContent='Recherche en cours…';
 try{
  const response=await fetch('https://photon.komoot.io/api/?limit=5&lang=fr&q='+encodeURIComponent(q),{headers:{Accept:'application/json'}});
  if(!response.ok)throw Error('Recherche indisponible');const data=await response.json();const hits=(data.features||[]).filter(f=>f.geometry?.coordinates?.length>=2);
  results.replaceChildren();if(!hits.length){results.textContent='Aucune adresse trouvée';return}
  hits.forEach(f=>{const p=f.properties||{};const label=[p.name,p.street&&p.street!==p.name?p.street:null,p.housenumber,p.postcode,p.city,p.country].filter(Boolean).join(', ');const b=document.createElement('button');b.type='button';b.textContent=label||'Destination';b.addEventListener('click',()=>motoGPSSelectDestination(f.geometry.coordinates,label));results.appendChild(b)})
 }catch(e){results.textContent='Recherche indisponible. Vérifiez la connexion Internet.'}
}
async function motoGPSSelectDestination(coords,label){
 const results=document.getElementById('moto-gps-search-results'),summary=document.getElementById('moto-gps-route-summary');if(results)results.hidden=true;
 const lat=Number(coords[1]),lng=Number(coords[0]);motoGPSCurrentDestination={lat,lng,label};
 if(motoGPSMap){if(motoGPSDestinationMarker)motoGPSDestinationMarker.setLatLng([lat,lng]);else motoGPSDestinationMarker=L.marker([lat,lng]).addTo(motoGPSMap);if(!motoGPSNavFix)motoGPSMap.setView([lat,lng],13)}
 if(summary){summary.hidden=false;summary.textContent='Calcul de l’itinéraire…'}
 try{
  let start=motoGPSLastFix;if(!start){start=await new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('GPS indisponible'));navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),reject,{enableHighAccuracy:true,timeout:12000})})}
  const url='https://router.project-osrm.org/route/v1/driving/'+start.lng+','+start.lat+';'+lng+','+lat+'?overview=full&geometries=geojson&steps=false';
  const response=await fetch(url);if(!response.ok)throw Error('Itinéraire indisponible');const data=await response.json();const route=data.routes?.[0];if(!route?.geometry?.coordinates?.length)throw Error('Aucun itinéraire trouvé');
  const points=route.geometry.coordinates.map(p=>[p[1],p[0]]);if(motoGPSMap){if(motoGPSRouteLine)motoGPSRouteLine.setLatLngs(points);else motoGPSRouteLine=L.polyline(points,{color:'#168bff',weight:7,opacity:.95}).addTo(motoGPSMap);motoGPSRoutePoints=points;motoGPSNavRecenter()}
  const km=(route.distance/1000).toLocaleString('fr-FR',{maximumFractionDigits:1});const min=Math.round(route.duration/60);if(summary){summary.replaceChildren();const t=document.createElement('span');t.textContent='📍 '+label+' · '+km+' km · '+(min>=60?Math.floor(min/60)+' h '+String(min%60).padStart(2,'0'):min+' min');const b=document.createElement('button');b.textContent='✕';b.setAttribute('aria-label','Effacer le trajet');b.onclick=motoGPSClearRoute;summary.append(t,b)}
 }catch(e){if(summary)summary.textContent='Impossible de calculer le trajet. Vérifiez le GPS et la connexion.'}
}
function motoGPSClearRoute(){if(motoGPSMap&&motoGPSRouteLine)motoGPSMap.removeLayer(motoGPSRouteLine);if(motoGPSMap&&motoGPSDestinationMarker)motoGPSMap.removeLayer(motoGPSDestinationMarker);motoGPSRouteLine=null;motoGPSDestinationMarker=null;motoGPSCurrentDestination=null;motoGPSRoutePoints=[];const e=document.getElementById('moto-gps-route-summary');if(e){e.hidden=true;e.replaceChildren()}const input=document.getElementById('moto-gps-destination');if(input)input.value=''}

function motoGPSUpdate(){const e=id=>document.getElementById(id);if(!e('moto-gps-speed'))return;e('moto-gps-speed').textContent=Math.round(motoGPSLastSpeed);e('moto-gps-angle').textContent=motoGPSZero===null?'—':Math.abs(motoGPSAngle).toFixed(1)+'°';e('moto-gps-side').textContent=motoGPSZero===null?'Calibration nécessaire':Math.abs(motoGPSAngle)<1?'Vertical':motoGPSAngle<0?'GAUCHE':'DROITE';let km=0;for(let i=1;i<motoGPSPoints.length;i++)km+=motoDistance([motoGPSPoints[i-1].lat,motoGPSPoints[i-1].lng],[motoGPSPoints[i].lat,motoGPSPoints[i].lng]);e('moto-gps-distance').textContent=km.toFixed(2).replace('.',',')+' km';let sec=motoGPSStartedAt?Math.round((Date.now()-motoGPSStartedAt)/1000):0;e('moto-gps-duration').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');e('moto-gps-max').textContent='Max '+Math.round(Math.max(0,...motoGPSPoints.map(p=>p.speed||0)))+' km/h'}
/* Require repeated close sensor samples before accepting a new peak, rejecting one-frame spikes. */
function motoGPSRecordLean(angle){
 if(motoGPSWatch===null||motoGPSZero===null||!Number.isFinite(angle))return;
 if(Math.abs(angle)>65){motoGPSStableAngle=null;motoGPSStableCount=0;return}
 if(motoGPSStableAngle!==null&&Math.abs(angle-motoGPSStableAngle)<7)motoGPSStableCount++;
 else motoGPSStableCount=1;
 motoGPSStableAngle=angle;
 if(motoGPSStableCount>=3){motoGPSLeft=Math.max(motoGPSLeft,Math.max(0,-angle));motoGPSRight=Math.max(motoGPSRight,Math.max(0,angle))}
}
async function motoGPSCalibrate(){if(typeof DeviceOrientationEvent==='undefined'){toast('Capteur d’orientation indisponible');return}try{if(typeof DeviceOrientationEvent.requestPermission==='function'){const result=await DeviceOrientationEvent.requestPermission();if(result!=='granted'){toast('Autorisation du capteur refusée');return}}if(!motoGPSMotion){motoGPSMotion=e=>{if(e.gamma==null)return;if(motoGPSZero===null)return;let delta=e.gamma-motoGPSZero;delta=((delta+180)%360+360)%360-180;motoGPSAngle=Math.max(-90,Math.min(90,delta));motoGPSRecordLean(motoGPSAngle);motoGPSUpdate()};window.addEventListener('deviceorientation',motoGPSMotion)}const once=e=>{if(e.gamma==null){toast('Orientation indisponible');return}motoGPSZero=e.gamma;motoGPSAngle=0;motoGPSStableAngle=null;motoGPSStableCount=0;motoGPSUpdate();toast('Position verticale calibrée')};window.addEventListener('deviceorientation',once,{once:true});toast('Maintenez la moto verticale et immobile')}catch{toast('Capteur non autorisé')}}
function motoGPSStart(){if(!navigator.geolocation){toast('Géolocalisation indisponible');return}if(motoGPSWatch!==null)return;motoGPSPoints=[];motoGPSLastFix=null;motoGPSLeft=0;motoGPSRight=0;motoGPSStableAngle=null;motoGPSStableCount=0;motoGPSStartedAt=Date.now();motoGPSLastSpeed=0;const start=document.getElementById('moto-gps-start'),stop=document.getElementById('moto-gps-stop');if(start)start.disabled=true;if(stop)stop.disabled=false;motoGPSWatch=navigator.geolocation.watchPosition(p=>{const c=p.coords;if(c.accuracy>100)return;const t=Date.now();let speed=Number.isFinite(c.speed)&&c.speed>=0?c.speed*3.6:0;if(!speed&&motoGPSLastFix){let dt=(t-motoGPSLastFix.t)/1000;if(dt>0)speed=Math.min(250,motoDistance([motoGPSLastFix.lat,motoGPSLastFix.lng],[c.latitude,c.longitude])*3600/dt)}motoGPSLastSpeed=speed;const point={lat:c.latitude,lng:c.longitude,t,speed,accuracy:c.accuracy,left:motoGPSLeft,right:motoGPSRight,angle:motoGPSZero===null?null:motoGPSAngle};if(!motoGPSLastFix||motoDistance([motoGPSLastFix.lat,motoGPSLastFix.lng],[point.lat,point.lng])>0.003){motoGPSPoints.push(point);motoGPSLastFix=point}if(motoGPSMap){const ll=[c.latitude,c.longitude];if(!motoGPSMarker)motoGPSMarker=L.circleMarker(ll,{radius:9,color:'#fff',weight:3,fillColor:'#278aff',fillOpacity:1}).addTo(motoGPSMap);else motoGPSMarker.setLatLng(ll);motoGPSLine?.setLatLngs(motoGPSPoints.map(x=>[x.lat,x.lng]));/* Camera controlled independently by motoGPSNavPosition */}motoGPSUpdate()},err=>toast('GPS : '+err.message),{enableHighAccuracy:true,maximumAge:1000,timeout:15000});motoGPSUpdate();toast('Enregistrement démarré')}
function motoGPSStop(){if(motoGPSWatch===null)return;navigator.geolocation.clearWatch(motoGPSWatch);motoGPSWatch=null;const points=motoGPSPoints.slice(),duration=Math.round((Date.now()-motoGPSStartedAt)/1000);let km=0;for(let i=1;i<points.length;i++)km+=motoDistance([points[i-1].lat,points[i-1].lng],[points[i].lat,points[i].lng]);if(points.length>1){const entry={id:motoId(),name:'Balade GPS '+new Date().toLocaleDateString('fr-FR'),date:new Date().toISOString(),km,points:points.length,duration,geometry:points.map(p=>[p.lat,p.lng]),telemetry:points,maxSpeed:Math.max(...points.map(p=>p.speed||0)),maxLeft:motoGPSLeft,maxRight:motoGPSRight};put('moto_gpx_history_v1',[entry,...motoHistory()]);toast('Balade enregistrée')}else toast('Pas assez de positions GPS pour enregistrer');motoGPSStartedAt=0;motoGPSPoints=[];motoGPSLeave()}
function motoGPSLeave(){if(motoGPSWatch!==null){if(!confirm('Arrêter et enregistrer la balade avant de quitter ?'))return;motoGPSStop();return}motoGPSNavStop();if(motoGPSMap){motoGPSMap.remove();motoGPSMap=null;motoGPSMarker=null;motoGPSLine=null;motoGPSRouteLine=null;motoGPSDestinationMarker=null;motoGPSCurrentDestination=null}if(motoGPSMotion){window.removeEventListener('deviceorientation',motoGPSMotion);motoGPSMotion=null}motoGPSZero=null;document.body.classList.remove('moto-gps-fullscreen');motoHome()}

function motoHome(){
 setHead('Roadtrip Moto','Préparez vos routes et points de passage');
 const rides=motoSaved().slice().sort((a,b)=>(b.updated||0)-(a.updated||0));
 content(`<div class="card stack"><h2 style="margin:0">Mes balades</h2><button class="btn primary" onclick="motoGPSOpen()">🏍️ GPS moto en direct</button><button class="btn" onclick="motoNew()">＋ Créer une balade</button></div>${rides.map(r=>`<div class="card"><div class="row" style="justify-content:space-between;align-items:center"><div><strong>${esc(r.name)}</strong><p class="small">${(r.points||[]).length} points · ${r.km!=null?Math.round(r.km)+' km':'trajet à calculer'}</p></div><button class="btn" onclick="motoOpen('${r.id}')">Ouvrir</button></div></div>`).join('')||'<div class="card">Aucune balade enregistrée.</div>'}<div class="card stack"><h2 style="margin:0">📍 Historique GPS</h2><p class="small">Importe une trace GPX enregistrée par une application GPS pendant ta navigation avec Google Maps.</p><label class="btn primary" for="moto-gpx-import" style="text-align:center">Importer un fichier GPX</label><input id="moto-gpx-import" type="file" accept=".gpx,application/gpx+xml,application/xml,text/xml" style="display:none" onchange="motoImportGPX(this)"><div id="moto-gpx-history">${motoHistoryMarkup()}</div></div>`);
}

const motoHistory=()=>get('moto_gpx_history_v1',[]);
function motoDistance(a,b){const R=6371,rad=x=>x*Math.PI/180,dLat=rad(b[0]-a[0]),dLon=rad(b[1]-a[1]),v=Math.sin(dLat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(v)))}
function motoHistoryMarkup(){const h=motoHistory().slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return h.map(x=>`<div class="moto-history-item"><div><strong>${esc(x.name)}</strong><div class="small">${x.date?nexoDisplayDate(x.date):'Date inconnue'} · ${x.km.toLocaleString('fr-FR',{maximumFractionDigits:1})} km${x.duration!=null?' · '+Math.round(x.duration/60)+' min':''}${Number.isFinite(x.maxLeft)&&Number.isFinite(x.maxRight)?'<div>Inclinaison max : ◀ '+x.maxLeft.toFixed(1)+'° gauche · '+x.maxRight.toFixed(1)+'° droite ▶</div>':''}</div></div><div class="moto-history-actions"><button class="btn" onclick="motoHistoryOpen('${x.id}')">Voir</button><button class="btn danger" onclick="motoHistoryDelete('${x.id}')">×</button></div></div>`).join('')||'<p class="small">Aucune trace importée.</p>'}
async function motoImportGPX(input){const file=input.files?.[0];if(!file)return;if(file.size>12*1024*1024)return toast('Fichier GPX trop volumineux (12 Mo max)');try{const xml=new DOMParser().parseFromString(await file.text(),'application/xml');if(xml.querySelector('parsererror'))throw Error('GPX invalide');const named=tag=>Array.from(xml.getElementsByTagName('*')).filter(n=>n.localName===tag);if(!named('gpx').length)throw Error('Ce fichier n’est pas un GPX');const tracks=named('trkseg');const routes=named('rte');let segments=[];if(tracks.length){segments=tracks.map(seg=>Array.from(seg.children).filter(n=>n.localName==='trkpt'))}else if(routes.length){segments=routes.map(route=>Array.from(route.children).filter(n=>n.localName==='rtept'))}else{segments=[named('wpt')]}const parsed=segments.map(seg=>seg.map(node=>{const lat=Number(node.getAttribute('lat')),lng=Number(node.getAttribute('lon')),time=Array.from(node.children).find(n=>n.localName==='time')?.textContent||null;return {lat,lng,time}}).filter(pt=>Number.isFinite(pt.lat)&&Number.isFinite(pt.lng)&&Math.abs(pt.lat)<=90&&Math.abs(pt.lng)<=180)).filter(seg=>seg.length>0);const count=parsed.reduce((n,seg)=>n+seg.length,0);if(count<2)throw Error('Trace insuffisante : au moins deux positions nécessaires');let km=0,first=null,last=null;for(const seg of parsed){for(let i=0;i<seg.length;i++){const pt=seg[i];if(pt.time){const t=Date.parse(pt.time);if(Number.isFinite(t)){first=first===null? t:Math.min(first,t);last=last===null?t:Math.max(last,t)}}if(i){const prev=seg[i-1];const d=motoDistance([prev.lat,prev.lng],[pt.lat,pt.lng]);if(d<2)km+=d}}}if(km<=0)throw Error('Distance impossible à calculer');const stride=Math.max(1,Math.ceil(count/3500));let n=0;const geometry=parsed.flatMap((seg,i)=>{const a=seg.filter((pt,j)=>j%stride===0||j===seg.length-1).map(pt=>[pt.lat,pt.lng]);return i?[null,...a]:a});const name=(named('trk')[0]||named('rte')[0]);const title=Array.from(name?.children||[]).find(n=>n.localName==='name')?.textContent?.trim()||file.name.replace(/\.gpx$/i,'');const record={id:motoId(),name:title.slice(0,100),km:+km.toFixed(2),date:first?new Date(first).toISOString():new Date().toISOString(),duration:first!==null&&last!==null&&last>=first?(last-first)/1000:null,geometry,points:count};put('moto_gpx_history_v1',[record,...motoHistory()]);toast('Trace GPS importée');motoHome()}catch(e){toast(e.message||'Import GPX impossible')}finally{input.value=''}}
function motoHistoryDelete(id){if(!confirm('Supprimer cette trace de l’historique ?'))return;put('moto_gpx_history_v1',motoHistory().filter(x=>x.id!==id));motoHome()}
async function motoHistoryOpen(id){const r=motoHistory().find(x=>x.id===id);if(!r)return motoHome();setHead('Roadtrip Moto','Historique de balade');content(`<div class="bar"><button onclick="motoHome()">← Historique</button></div><div class="card stack"><h2>${esc(r.name)}</h2><p><strong>${r.km.toLocaleString('fr-FR',{maximumFractionDigits:1})} km</strong> · ${r.points} positions GPS${r.duration!=null?' · '+Math.round(r.duration/60)+' min':''}</p>${Number.isFinite(r.maxLeft)&&Number.isFinite(r.maxRight)?'<div class="moto-gps-history-lean"><div><small>Inclinaison max gauche</small><strong>'+r.maxLeft.toFixed(1)+'°</strong></div><div><small>Inclinaison max droite</small><strong>'+r.maxRight.toFixed(1)+'°</strong></div></div><p class="small">Inclinaisons estimées par le téléphone, non certifiées. Une fixation stable et un recalibrage sont nécessaires.</p>':''}<div id="moto-history-map" class="moto-map">Chargement de la carte…</div><p class="small">Distance calculée à partir des positions du fichier GPX, sans correction routière. La précision dépend de l’enregistrement GPS.</p><button class="btn danger" onclick="motoHistoryDelete('${r.id}')">Supprimer cette trace</button></div>`);try{await motoLoadLeaflet();if(!document.getElementById('moto-history-map'))return;if(motoMap){motoMap.remove();motoMap=null}motoMap=L.map('moto-history-map');L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(motoMap);const segments=[];let segment=[];for(const pt of r.geometry){if(pt===null){if(segment.length)segments.push(segment);segment=[]}else segment.push(pt)}if(segment.length)segments.push(segment);const layer=L.polyline(segments,{color:'#2687ef',weight:5}).addTo(motoMap);motoMap.fitBounds(layer.getBounds().pad(.12));setTimeout(()=>motoMap?.invalidateSize(),100)}catch{const el=document.getElementById('moto-history-map');if(el)el.textContent='Carte indisponible : vérifiez votre connexion.'}}

function motoNew(){const r={id:motoId(),name:'Nouvelle balade',points:[],km:null,updated:Date.now()};put('moto_rides_v1',[r,...motoSaved()]);motoOpen(r.id)}
function motoGet(){return motoSaved().find(x=>x.id===motoSelected)}
function motoUpdate(fn){const rides=motoSaved(),r=rides.find(x=>x.id===motoSelected);if(!r)return;fn(r);r.updated=Date.now();put('moto_rides_v1',rides)}
function motoLoadLeaflet(){return new Promise((resolve,reject)=>{if(window.L)return resolve();if(document.querySelector('#moto-leaflet-js')){let count=0;const poll=setInterval(()=>{if(window.L){clearInterval(poll);resolve()}else if(++count>50){clearInterval(poll);reject(Error('Carte indisponible'))}},100);return}let css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(css);let script=document.createElement('script');script.id='moto-leaflet-js';script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.onload=resolve;script.onerror=()=>{script.remove();css.remove();reject(Error('Carte indisponible'))};document.head.appendChild(script)})}
function motoOpen(id){motoSelected=id;const r=motoGet();if(!r)return motoHome();setHead('Roadtrip Moto','Construire un itinéraire');content(`<div class="bar"><button onclick="motoHome()">← Mes balades</button></div><div class="card stack"><label>Nom de la balade</label><input class="field" id="moto-name" maxlength="100" value="${esc(r.name)}" onchange="motoRename(this.value)"><p class="moto-note">Touchez la carte pour placer des étapes dans l'ordre du trajet. Le tracé suit les routes lorsqu'un service de calcul est disponible.</p><div id="moto-map" class="moto-map"><div class="moto-map-fallback">Chargement de la carte…</div></div><div class="moto-form"><input class="field" id="moto-place" placeholder="Rechercher une ville ou une adresse" aria-label="Lieu à rechercher"><button class="btn" onclick="motoSearch()">Rechercher</button></div><div id="moto-info" class="moto-info" aria-live="polite"></div><div id="moto-stops"></div><div class="moto-actions"><button class="btn" onclick="motoUndo()">↶ Retirer le dernier point</button><button class="btn" onclick="motoReverse()">⇄ Inverser</button><button class="btn danger" onclick="motoClear()">Effacer les points</button></div><div class="moto-actions"><button class="btn primary" onclick="motoMaps()">↗ Ouvrir dans Google Maps</button><button class="btn" onclick="motoGPX()">Exporter GPX</button></div><p class="moto-note">Google Maps peut recalculer le parcours et limiter le nombre d'étapes. L'export GPX conserve les points et, si calculé, le tracé routier. Connexion Internet requise pour la carte et le calcul d'itinéraire.</p><button class="btn danger" onclick="motoDelete()">Supprimer cette balade</button></div>`);motoStartMap(id)}
function motoRename(v){motoUpdate(r=>r.name=v.trim()||'Nouvelle balade')}
async function motoStartMap(id){try{await motoLoadLeaflet();if(motoSelected!==id||!$('#moto-map'))return;if(motoMap){motoMap.remove();motoMap=null}motoMap=L.map('moto-map',{zoomControl:true}).setView([48.85,2.35],9);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(motoMap);motoLayer=L.layerGroup().addTo(motoMap);motoMap.on('click',e=>motoAdd(e.latlng.lat,e.latlng.lng));motoRefresh(true);setTimeout(()=>motoMap?.invalidateSize(),100)}catch(e){if($('#moto-map'))$('#moto-map').innerHTML='<div class="moto-map-fallback">Carte indisponible. Vérifiez votre connexion Internet et réessayez en rouvrant la balade.</div>';motoRefresh(false)}}
function motoAdd(lat,lng,label){if(!Number.isFinite(lat)||!Number.isFinite(lng))return;const r=motoGet();if(!r||r.points.length>=35)return toast('35 points maximum');motoUpdate(r=>{r.points.push({lat:+lat.toFixed(6),lng:+lng.toFixed(6),label:label||'Point '+(r.points.length+1)});r.km=null;r.geometry=null});motoRefresh(true)}
function motoUndo(){motoUpdate(r=>{r.points.pop();r.km=null;r.geometry=null});motoRefresh(true)}
function motoReverse(){motoUpdate(r=>{r.points.reverse();r.km=null;r.geometry=null});motoRefresh(true)}
function motoClear(){if(!confirm('Effacer tous les points de la balade ?'))return;motoUpdate(r=>{r.points=[];r.km=null;r.geometry=null});motoRefresh(true)}
function motoRemove(i){motoUpdate(r=>{r.points.splice(i,1);r.km=null;r.geometry=null});motoRefresh(true)}
function motoRefresh(route){const r=motoGet();if(!r)return;const pts=r.points||[];const stops=$('#moto-stops');if(stops)stops.innerHTML=pts.map((p,i)=>`<div class="moto-stop"><strong>${i+1}.</strong><span>${esc(p.label||'Point '+(i+1))}<br><small>${p.lat.toFixed(4)}, ${p.lng.toFixed(4)}</small></span><button class="btn" aria-label="Supprimer le point ${i+1}" onclick="motoRemove(${i})">×</button></div>`).join('')||'<p class="small">Aucun point : touchez la carte pour commencer.</p>';const info=$('#moto-info');if(info)info.textContent=pts.length+' point(s)'+(r.km!=null?' · '+Math.round(r.km*10)/10+' km par la route':'');if(!motoMap||!motoLayer)return;motoLayer.clearLayers();pts.forEach((p,i)=>L.marker([p.lat,p.lng]).addTo(motoLayer).bindPopup(esc((i+1)+'. '+(p.label||'Étape'))));if(motoRoute){motoMap.removeLayer(motoRoute);motoRoute=null}if(pts.length){const bounds=L.latLngBounds(pts.map(p=>[p.lat,p.lng]));motoMap.fitBounds(bounds.pad(.25),{maxZoom:12})}if(route)motoCalculate();else if(r.geometry&&r.geometry.length>1)motoDrawRoute(r.geometry)}
function motoDrawRoute(coords){if(!motoMap||!coords||coords.length<2)return;motoRoute=L.polyline(coords,{color:'#2687ef',weight:5,opacity:.88}).addTo(motoMap)}
async function motoCalculate(){const r=motoGet();if(!r)return;const id=r.id,points=r.points.map(p=>({...p})),req=++motoRequest;if(points.length<2)return;const info=$('#moto-info');if(info)info.textContent='Calcul du trajet routier…';try{const coord=points.map(p=>p.lng+','+p.lat).join(';');const url='https://router.project-osrm.org/route/v1/driving/'+coord+'?overview=full&geometries=geojson&steps=false';const res=await fetch(url);if(!res.ok)throw Error('Routage indisponible');const data=await res.json();const route=data.routes?.[0];if(!route?.geometry?.coordinates?.length)throw Error('Aucun trajet trouvé');if(req!==motoRequest||motoSelected!==id)return;const geometry=route.geometry.coordinates.map(x=>[x[1],x[0]]);motoUpdate(r=>{r.km=route.distance/1000;r.geometry=geometry});motoRefresh(false)}catch(e){if(req!==motoRequest)return;const el=$('#moto-info');if(el)el.textContent=points.length+' points · Impossible de calculer la route actuellement. Réessayez en modifiant un point.'}}
async function motoSearch(){const input=$('#moto-place');const q=input?.value.trim();if(!q)return;try{const res=await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q='+encodeURIComponent(q),{headers:{'Accept-Language':'fr'}});if(!res.ok)throw Error();const items=await res.json();if(!items.length)return toast('Lieu introuvable');const item=items[0],lat=Number(item.lat),lng=Number(item.lon);if(motoMap)motoMap.setView([lat,lng],12);if(confirm('Ajouter « '+item.display_name.split(',').slice(0,2).join(',')+' » comme étape ?'))motoAdd(lat,lng,item.display_name.split(',').slice(0,2).join(','));input.value=''}catch{toast('Recherche indisponible')}}
function motoMaps(){const r=motoGet(),pts=r?.points||[];if(pts.length<2)return toast('Ajoutez au moins 2 points');const fmt=p=>p.lat+','+p.lng;const mid=pts.slice(1,-1);if(mid.length>3){if(!confirm('Google Maps sur iPhone peut limiter les étapes et recalculer le parcours. Ouvrir les 5 premiers points ?'))return}const selected=pts.length>5?pts.slice(0,5):pts;const url='https://www.google.com/maps/dir/?api=1&travelmode=driving&origin='+encodeURIComponent(fmt(selected[0]))+'&destination='+encodeURIComponent(fmt(selected.at(-1)))+(selected.length>2?'&waypoints='+encodeURIComponent(selected.slice(1,-1).map(fmt).join('|')):'');window.open(url,'_blank','noopener')}
function motoGPX(){const r=motoGet();if(!r||r.points.length<2)return toast('Ajoutez au moins 2 points');const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));const waypoints=r.points.map(p=>`<wpt lat="${p.lat}" lon="${p.lng}"><name>${xml(p.label||'Étape')}</name></wpt>`).join('');const track=r.geometry?.length?`<trk><name>${xml(r.name)}</name><trkseg>${r.geometry.map(p=>`<trkpt lat="${p[0]}" lon="${p[1]}"/>`).join('')}</trkseg></trk>`:'';const data='<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="NEXO" xmlns="http://www.topografix.com/GPX/1/1"><metadata><name>'+xml(r.name)+'</name></metadata>'+waypoints+track+'</gpx>';const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type:'application/gpx+xml'}));a.href=u;a.download='nexo-balade-'+r.id+'.gpx';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function motoDelete(){if(!confirm('Supprimer définitivement cette balade ?'))return;put('moto_rides_v1',motoSaved().filter(r=>r.id!==motoSelected));motoSelected=null;motoHome()}

// GEN 2.6.63 — voyages dans IndexedDB, hors quota localStorage.
// Le cache mémoire garde l'API synchrone des écrans existants.
let nxTravelCache=get('travel_v10',[]),nxTravelReady=false,nxTravelQueue=Promise.resolve(),nxTravelDbPromise=null;
function nxTravelDb(){
 if(!nxTravelDbPromise)nxTravelDbPromise=new Promise((resolve,reject)=>{
  if(!window.indexedDB)return reject(Error('IndexedDB indisponible'));
  const req=indexedDB.open('nexo-local-data',1);
  req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('data'))req.result.createObjectStore('data')};
  req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('Ouverture IndexedDB impossible'));
 });
 return nxTravelDbPromise;
}
async function nxTravelRead(){const db=await nxTravelDb();return new Promise((resolve,reject)=>{
 const tx=db.transaction('data','readonly'),req=tx.objectStore('data').get('travel_v10');
 req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);
})}
async function nxTravelWrite(items){const db=await nxTravelDb();return new Promise((resolve,reject)=>{
 const tx=db.transaction('data','readwrite');tx.objectStore('data').put(items,'travel_v10');
 tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Transaction annulée'));
})}
const travelStore=()=>nxTravelCache;
function travelSave(items){
 nxTravelCache=items;
 // Sérialise les écritures afin d'éviter qu'une ancienne sauvegarde écrase la dernière.
 nxTravelQueue=nxTravelQueue.then(()=>nxTravelWrite(items)).catch(e=>{
  console.error('NEXO : écriture voyage échouée',e);
  alert('Sauvegarde du voyage impossible : '+(e.message||e)+'. Conserve ta sauvegarde complète.');
 });
 return nxTravelQueue;
}
async function nxTravelInitialize(){
 try{
  const stored=await nxTravelRead();
  if(Array.isArray(stored)){
   // En cas de modifications précoces avant la fin de l'initialisation, ne pas les écraser.
   if(!nxTravelReady)nxTravelCache=stored;
  }else{
   const legacy=get('travel_v10',[]);
   if(legacy.length)await nxTravelWrite(legacy);
   nxTravelCache=legacy;
  }
  // Supprimer l'ancienne copie uniquement APRÈS vérification de l'écriture IndexedDB.
  if(localStorage.getItem('tb_travel_v10')!==null){
   const verified=await nxTravelRead();
   if(Array.isArray(verified))localStorage.removeItem('tb_travel_v10');
  }
  nxTravelReady=true;
 }catch(e){
  console.error('NEXO : migration IndexedDB non disponible',e);
  nxTravelReady=false;
  alert('Stockage IndexedDB indisponible. Les anciens voyages restent dans le stockage d’origine ; conserve ta sauvegarde.');
 }
}
const nxTravelStartup=nxTravelInitialize();
// GEN 2.6.70 : actualiser l'accueil après hydratation asynchrone IndexedDB.
// Ne pas naviguer de force si l'utilisateur a déjà quitté l'accueil.
nxTravelStartup.then(()=>nxTravelQueue).then(()=>{
 if(document.querySelector('.gen2-shell') && current==='home'){
  const grid=document.querySelector('.gen2-grid');
  if(grid){const ids=gen2Config();grid.innerHTML=ids.map(gen2Card).join('')}
  const upcoming=document.querySelector('.gen26-upcoming');
  if(upcoming){const card=upcoming.querySelector('.gen26-trip-card, .gen26-trip-empty');if(card)card.outerHTML=gen26UpcomingTrip()}
 }
}).catch(e=>console.error('NEXO : rafraîchissement voyages',e));
