/* NEXO V13 — Santé / Nutrition, local-first. AI integration intentionally disabled
   until a secured backend is configured; no secrets or remote uploads. */
const nutritionDefaults={calories:2000,protein:100,carbs:220,fat:70};
const nutritionFoods=[
 {name:'Poulet, blanc cuit',kcal:165,p:31,c:0,f:3.6},
 {name:'Riz blanc cuit',kcal:130,p:2.7,c:28.2,f:0.3},
 {name:'Pâtes cuites',kcal:158,p:5.8,c:30.9,f:0.9},
 {name:'Brocoli cuit',kcal:35,p:2.4,c:7.2,f:0.4},
 {name:'Pomme',kcal:52,p:0.3,c:13.8,f:0.2},
 {name:'Banane',kcal:89,p:1.1,c:22.8,f:0.3},
 {name:'Œuf entier',kcal:143,p:12.6,c:0.7,f:9.5},
 {name:'Saumon cuit',kcal:206,p:22.1,c:0,f:12.4},
 {name:'Pommes de terre cuites',kcal:87,p:1.9,c:20.1,f:0.1},
 {name:'Yaourt nature',kcal:61,p:3.5,c:4.7,f:3.3},
 {name:'Pain',kcal:265,p:9,c:49,f:3.2},
 {name:'Huile d’olive',kcal:884,p:0,c:0,f:100}
];
let nutritionDate=new Date().toLocaleDateString('en-CA'),nutritionEditing=null;
function nutritionItems(){return get('nutritionMeals',[])}
function nutritionTargets(){return Object.assign({},nutritionDefaults,get('nutritionTargets',{}))}
function nutritionTotals(items){return items.reduce((a,x)=>{for(const k of ['kcal','p','c','f'])a[k]+=Number(x[k])||0;return a},{kcal:0,p:0,c:0,f:0})}
function nutritionFmt(n){return (Math.round((Number(n)||0)*10)/10).toLocaleString('fr-FR',{maximumFractionDigits:1})}
function nutritionDateTitle(d){return nexoDisplayDate(d)}
function nutrition(){nutritionRender()}
function nutritionRender(){
 setHead('Nutrition & Calories','Santé · suivi alimentaire hors ligne');
 const targets=nutritionTargets(),items=nutritionItems().filter(x=>x.date===nutritionDate).sort((a,b)=>String(b.created||'').localeCompare(String(a.created||''))),tot=nutritionTotals(items);
 const bars=[['Calories',tot.kcal,targets.calories,'kcal'],['Protéines',tot.p,targets.protein,'g'],['Glucides',tot.c,targets.carbs,'g'],['Lipides',tot.f,targets.fat,'g']];
 content(`<div class="nutrition-top"><label for="nutritionDate">Journée</label><input id="nutritionDate" type="date" class="field" value="${esc(nutritionDate)}" onchange="nutritionDate=this.value;nutritionRender()"></div>
 <div class="card stack"><h2>Bilan du jour</h2><div class="nutrition-total">${nutritionFmt(tot.kcal)} <small>/ ${nutritionFmt(targets.calories)} kcal</small></div>
 ${bars.map(([name,v,goal,unit])=>`<div class="nutrition-progress"><div><strong>${name}</strong><span>${nutritionFmt(v)} / ${nutritionFmt(goal)} ${unit}</span></div><div class="nutrition-track"><div style="width:${Math.min(100,Math.max(0,goal?v/goal*100:0))}%"></div></div></div>`).join('')}
 <div class="nutrition-actions"><button class="btn primary" onclick="nutritionForm()">+ Ajouter un repas</button><button class="btn" onclick="nutritionSettings()">Objectifs</button></div></div>
 <div class="card stack"><h2>Repas enregistrés (${items.length})</h2>${items.map(x=>`<div class="nutrition-meal"><div><strong>${esc(x.name)}</strong><small>${esc(x.type)} · ${nutritionFmt(x.kcal)} kcal</small><small>P ${nutritionFmt(x.p)} g · G ${nutritionFmt(x.c)} g · L ${nutritionFmt(x.f)} g</small></div><div class="nutrition-meal-buttons"><button class="btn" onclick="nutritionForm('${x.id}')">Modifier</button><button class="btn danger" onclick="nutritionDelete('${x.id}')">×</button></div></div>`).join('')||'<p class="muted">Aucun repas enregistré pour cette journée.</p>'}</div>
 <div class="card stack"><h3>Analyse par photo avec OpenAI</h3><p class="small">Fonction à activer ultérieurement. Elle nécessitera Internet et un service sécurisé : aucune photo n’est envoyée actuellement.</p><button class="btn" onclick="toast('Analyse IA non configurée : aucun envoi de photo')">📷 Analyse IA (à venir)</button></div>
 <div class="card"><p class="small">Les valeurs nutritionnelles sont des estimations. Vérifie les portions et les glucides, particulièrement pour toute décision liée à l’insuline.</p></div>`);
}
function nutritionForm(id){
 const item=id?nutritionItems().find(x=>x.id===id):null;nutritionEditing=id||null;
 const d=item||{date:nutritionDate,type:'Déjeuner',name:'',grams:100,kcal:0,p:0,c:0,f:0};
 content(`<div class="bar"><button onclick="nutritionRender()">← Journal</button></div><div class="card stack nutrition-form"><h2>${item?'Modifier le repas':'Ajouter un repas'}</h2>
 <label>Type de repas<select id="nutritionType" class="field">${['Petit-déjeuner','Déjeuner','Dîner','Collation'].map(v=>`<option ${d.type===v?'selected':''}>${v}</option>`).join('')}</select></label>
 <label>Aliment de référence (facultatif)<select id="nutritionPreset" class="field" onchange="nutritionApplyPreset()"><option value="">Saisie personnalisée</option>${nutritionFoods.map((f,i)=>`<option value="${i}">${esc(f.name)}</option>`).join('')}</select></label>
 <label>Nom du plat / aliment<input id="nutritionName" class="field" maxlength="120" value="${esc(d.name)}" placeholder="Ex. Poulet, riz et légumes"></label>
 <label>Quantité (g) — utilisée pour le calcul par référence<input id="nutritionGrams" class="field" type="number" min="1" max="10000" step="1" value="${Number(d.grams)||100}" oninput="nutritionRecalc()"></label>
 <div class="nutrition-fields"><label>Calories (kcal)<input id="nutritionKcal" class="field" type="number" min="0" max="20000" step="0.1" value="${Number(d.kcal)||0}"></label>
 <label>Protéines (g)<input id="nutritionP" class="field" type="number" min="0" max="1000" step="0.1" value="${Number(d.p)||0}"></label>
 <label>Glucides (g)<input id="nutritionC" class="field" type="number" min="0" max="1000" step="0.1" value="${Number(d.c)||0}"></label>
 <label>Lipides (g)<input id="nutritionF" class="field" type="number" min="0" max="1000" step="0.1" value="${Number(d.f)||0}"></label></div>
 <p class="small">Références indicatives par 100 g. Pour un plat composé, additionne les ingrédients ou renseigne les valeurs de l’étiquette. Tous les chiffres restent modifiables.</p>
 <button class="btn primary" onclick="nutritionSave()">Enregistrer le repas</button><button class="btn" onclick="nutritionRender()">Annuler</button></div>`);
}
function nutritionApplyPreset(){const i=$('#nutritionPreset').value;if(i==='')return;const f=nutritionFoods[Number(i)];$('#nutritionName').value=f.name;nutritionRecalc()}
function nutritionRecalc(){const i=$('#nutritionPreset')?.value;if(i===undefined||i==='')return;const f=nutritionFoods[Number(i)],grams=Number($('#nutritionGrams').value);if(!f||!Number.isFinite(grams)||grams<=0)return;for(const [id,key] of [['nutritionKcal','kcal'],['nutritionP','p'],['nutritionC','c'],['nutritionF','f']])$('#'+id).value=(f[key]*grams/100).toFixed(1)}
function nutritionSave(){
 const name=$('#nutritionName').value.trim(),grams=Number($('#nutritionGrams').value);
 const vals=['nutritionKcal','nutritionP','nutritionC','nutritionF'].map(id=>Number($('#'+id).value));
 if(!name||!Number.isFinite(grams)||grams<=0||grams>10000||vals.some(v=>!Number.isFinite(v)||v<0||v>20000))return toast('Vérifie les valeurs du repas');
 const old=nutritionItems(),existing=old.find(x=>x.id===nutritionEditing);
 const record={id:existing?.id||travelNewId(),created:existing?.created||new Date().toISOString(),date:existing?.date||nutritionDate,type:$('#nutritionType').value,name,grams,kcal:vals[0],p:vals[1],c:vals[2],f:vals[3]};
 put('nutritionMeals',existing?old.map(x=>x.id===record.id?record:x):[...old,record]);nutritionEditing=null;nutritionRender();toast('Repas enregistré hors ligne')
}
