 if(!data.plans.every(p=>p&&typeof p.id==='string'&&p.id&&p.vehicleId===vehicle.id&&typeof p.name==='string')||!data.records.every(r=>r&&typeof r.id==='string'&&r.id&&r.vehicleId===vehicle.id))return alert('L’historique du fichier est incohérent.');
 const idsUnique=arr=>new Set(arr.map(x=>x.id)).size===arr.length;if(!idsUnique(data.plans)||!idsUnique(data.records)||!idsUnique(data.expenses))return alert('Le fichier contient des identifiants en double.');
