 const newId=garageUid(),planIds=new Map(data.plans.map(p=>[p.id,garageUid()])),recordIds=new Map(data.records.map(r=>[r.id,garageUid()])),expenseIds=new Map(data.expenses.map(e=>[e.id,garageUid()]));
