 if(garageHistoryYear!=='total'&&!years.includes(garageHistoryYear))garageHistoryYear='total';
 const filtered=records.filter(r=>garageHistoryYear==='total'||String(r.date||'').slice(0,4)===garageHistoryYear).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
