function garageCosts(v,records){const total=records.reduce((n,r)=>n+Number(r.cost||0),0),yearRecords=records.filter(r=>garageHistoryYear==='total'||String(r.date||'').startsWith(garageHistoryYear)),annual=yearRecords.reduce((n,r)=>n+Number(r.cost||0),0),labels=garageHistoryYear==='total'?[...new Set(records.map(r=>String(r.date||'').slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort():['J','F','M','A','M','J','J','A','S','O','N','D'],months=garageHistoryYear==='total'?labels.map(y=>records.filter(r=>String(r.date||'').startsWith(y)).reduce((n,r)=>n+Number(r.cost||0),0)):Array.from({length:12},(_,i)=>yearRecords.filter(r=>Number(r.date.slice(5,7))===i+1).reduce((n,r)=>n+Number(r.cost||0),0)),max=Math.max(1,...months);return `<div class="card stack"><h3>Dépenses d'entretien</h3><select class="field" aria-label="Filtrer les coûts par année" onchange="garageHistoryYear=this.value;garageRender()"><option value="total">Total</option>${[...new Set(records.map(r=>String(r.date||'').slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse().map(y=>`<option value="${y}" ${y===garageHistoryYear?'selected':''}>${y}</option>`).join('')}</select><div class="garage-kpis"><div><strong>${money(annual)}</strong><small>${garageHistoryYear==='total'?'Toutes les années':garageHistoryYear}</small></div><div><strong>${money(total)}</strong><small>Total</small></div><div><strong>${records.length}</strong><small>Interventions</small></div></div><div class="save-bar-chart garage-chart">${months.map((val,i)=>`<div class="save-bar-cell"><div class="save-bar-track"><div style="height:${Math.max(2,val/max*100)}%;width:65%;background:var(--accent,#348cff);border-radius:5px 5px 0 0" title="${money(val)}"></div></div><span>${labels[i]}</span></div>`).join('')}</div></div>`}

