/* GEN 2.6.5 — encrypted local vault and offline recipe book */
const vaultDBName='nexo-vault-v1';let vaultKey=null,vaultBusy=false,recipeTimerHandle=null,recipeSeconds=0,vaultAwayAt=0,vaultLockTimer=null;const vaultGraceMs=60000;
function vaultLock(){vaultKey=null;vaultBusy=false;vaultAwayAt=0;if(vaultLockTimer){clearTimeout(vaultLockTimer);vaultLockTimer=null}}
function vaultPause(){if(!vaultKey||vaultAwayAt)return;vaultAwayAt=Date.now();vaultLockTimer=setTimeout(()=>{if(vaultAwayAt&&Date.now()-vaultAwayAt>=vaultGraceMs)vaultLock()},vaultGraceMs)}
function vaultResume(){if(!vaultAwayAt)return;if(Date.now()-vaultAwayAt>=vaultGraceMs){vaultLock();return}vaultAwayAt=0;if(vaultLockTimer){clearTimeout(vaultLockTimer);vaultLockTimer=null}}
document.addEventListener('visibilitychange',()=>{if(document.hidden){vaultPause();if(current==='vault'){$('#vaultScreen')?.replaceChildren();}}else if(current==='vault'){vaultResume();vaultMustUnlock()}});
window.addEventListener('pagehide',vaultLock);
function vaultMustUnlock(){if(current==='vault')vault()}
function vaultDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(vaultDBName,1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('meta'))db.createObjectStore('meta');if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function vaultGet(store,key){const db=await vaultDb();return new Promise((resolve,reject)=>{const t=db.transaction(store,'readonly'),r=t.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);t.oncomplete=()=>db.close()})}
async function vaultPut(store,value,key){const db=await vaultDb();return new Promise((resolve,reject)=>{const t=db.transaction(store,'readwrite');if(key===undefined)t.objectStore(store).put(value);else t.objectStore(store).put(value,key);t.oncomplete=()=>{db.close();resolve()};t.onerror=()=>reject(t.error)})}
async function vaultAll(){const db=await vaultDb();return new Promise((resolve,reject)=>{const t=db.transaction('files','readonly'),r=t.objectStore('files').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);t.oncomplete=()=>db.close()})}
async function vaultRemove(id){const db=await vaultDb();return new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite');t.objectStore('files').delete(id);t.oncomplete=()=>{db.close();resolve()};t.onerror=()=>reject(t.error)})}
const vaultRand=n=>crypto.getRandomValues(new Uint8Array(n));
function vaultB64(a){let s='';for(const v of new Uint8Array(a))s+=String.fromCharCode(v);return btoa(s)}
function vaultBytes(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
async function vaultDerive(secret,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:vaultBytes(salt),iterations:310000,hash:'SHA-256'},key,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function vaultWrap(raw,secret){const salt=vaultB64(vaultRand(16)),iv=vaultRand(12),k=await vaultDerive(secret,salt);return {salt,iv:vaultB64(iv),data:vaultB64(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,raw))}}
async function vaultUnwrap(w,secret){const k=await vaultDerive(secret,w.salt);return crypto.subtle.decrypt({name:'AES-GCM',iv:vaultBytes(w.iv)},k,vaultBytes(w.data))}
function vaultRecovery(){return Array.from(vaultRand(32),b=>b.toString(16).padStart(2,'0')).join('').match(/.{1,8}/g).join('-')}
function vault(){vaultCategoryView=null;content('<div id="vaultScreen" class="stack"><p class="muted">Chargement du coffre-fort sécurisé…</p></div>');vaultStart()}
async function vaultStart(){try{vaultResume();const meta=await vaultGet('meta','config');if(current!=='vault')return;if(!meta){$('#vaultScreen').innerHTML=`<div class="card stack"><h2>🔐 Créer mon coffre-fort</h2><p class="muted">Documents chiffrés sur cet appareil. Le mot de passe sera redemandé après 1 minute hors du coffre-fort.</p><input class="field" type="password" id="vaultNewPass" autocomplete="new-password" placeholder="Mot de passe (12 caractères minimum)"><input class="field" type="password" id="vaultConfirm" autocomplete="new-password" placeholder="Confirmer le mot de passe"><button class="btn primary" onclick="vaultCreate()">Créer le coffre-fort</button></div>`;return}if(!vaultKey){$('#vaultScreen').innerHTML=`<div class="card stack"><h2>🔐 Coffre-fort verrouillé</h2><input class="field" type="password" id="vaultPassword" autocomplete="off" placeholder="Mot de passe principal"><button class="btn primary" onclick="vaultUnlock(false)">Déverrouiller</button><button class="btn" onclick="vaultRecoveryForm()">Mot de passe oublié ?</button></div>`;return}vaultShow()}catch(e){$('#vaultScreen').innerHTML='<div class="card">Stockage local indisponible sur cet appareil.</div>';console.error(e)}}
async function vaultCreate(){if(vaultBusy)return;const pass=$('#vaultNewPass').value;if(pass.length<12||pass!==$('#vaultConfirm').value)return toast('Mot de passe de 12 caractères minimum et confirmation identique');vaultBusy=true;try{const raw=vaultRand(32),recovery=vaultRecovery(),meta={version:1,pass:await vaultWrap(raw,pass),recovery:await vaultWrap(raw,recovery)};await vaultPut('meta',meta,'config');vaultKey=await crypto.subtle.importKey('raw',raw,'AES-GCM',true,['encrypt','decrypt']);$('#vaultScreen').innerHTML=`<div class="card stack"><h2>🔑 Ta clé de récupération</h2><p>Conserve cette clé hors de NEXO. Elle ne sera plus affichée après cette étape.</p><textarea class="field" id="vaultRecoveryCode" readonly rows="3">${recovery}</textarea><button class="btn" onclick="copyText($('#vaultRecoveryCode').value)">Copier la clé</button><label><input type="checkbox" id="vaultRecoveryConfirmed"> J'ai sauvegardé cette clé dans un endroit sûr</label><button class="btn primary" onclick="if(!$('#vaultRecoveryConfirmed').checked)return toast('Conserve la clé avant de continuer');vaultShow()">Accéder au coffre-fort</button></div>`}catch(e){toast('Impossible de créer le coffre-fort');console.error(e)}finally{vaultBusy=false}}
async function vaultUnlock(recover){if(vaultBusy)return;const el=$(recover?'#vaultRecoveryInput':'#vaultPassword'),secret=el?.value||'';if(!secret)return;vaultBusy=true;try{const meta=await vaultGet('meta','config'),raw=await vaultUnwrap(meta[recover?'recovery':'pass'],secret);vaultKey=await crypto.subtle.importKey('raw',raw,'AES-GCM',true,['encrypt','decrypt']);if(recover){$('#vaultScreen').innerHTML=`<div class="card stack"><h2>Définir un nouveau mot de passe</h2><input class="field" id="vaultNewPass" type="password" placeholder="Nouveau mot de passe (12 caractères minimum)"><input class="field" id="vaultConfirm" type="password" placeholder="Confirmer"><button class="btn primary" onclick="vaultResetPassword()">Enregistrer</button></div>`}else vaultShow()}catch(e){toast('Code incorrect ou données indisponibles')}finally{vaultBusy=false}}
function vaultRecoveryForm(){$('#vaultScreen').innerHTML=`<div class="card stack"><h2>🔑 Récupération</h2><p>Renseigne ta clé de récupération enregistrée lors de la création.</p><textarea class="field" id="vaultRecoveryInput" rows="3" placeholder="Clé de récupération"></textarea><button class="btn primary" onclick="vaultUnlock(true)">Vérifier la clé</button><button class="btn" onclick="vaultLock();vaultStart()">Retour</button></div>`}
async function vaultResetPassword(){const pass=$('#vaultNewPass').value;if(pass.length<12||pass!==$('#vaultConfirm').value)return toast('Mot de passe invalide ou confirmation différente');try{const meta=await vaultGet('meta','config'),raw=await crypto.subtle.exportKey('raw',vaultKey);meta.pass=await vaultWrap(raw,pass);await vaultPut('meta',meta,'config');vaultShow();toast('Mot de passe remplacé')}catch(e){toast('Erreur de récupération')}}
async function vaultEncrypt(bytes){if(!vaultKey)throw Error('Coffre verrouillé');const iv=vaultRand(12);return {iv:vaultB64(iv),data:vaultB64(await crypto.subtle.encrypt({name:'AES-GCM',iv},vaultKey,bytes))}}
async function vaultDecrypt(item){if(!vaultKey)throw Error('Coffre verrouillé');return crypto.subtle.decrypt({name:'AES-GCM',iv:vaultBytes(item.iv)},vaultKey,vaultBytes(item.data))}
let vaultCategoryView=null;
const vaultCategoryDefaults=[['Identité','🪪'],['Véhicules','🚗'],['Logement','🏠'],['Contrats & assurances','📄'],['Santé','🩺'],['Documents','📁']];
function vaultCategoryIcon(name){return vaultCategoryDefaults.find(x=>x[0]===name)?.[1]||'📂'}
function vaultSelectCategory(name){vaultCategoryView=name;vaultShow();window.scrollTo(0,0)}
function vaultAllCategories(){vaultCategoryView=null;vaultShow();window.scrollTo(0,0)}
async function vaultShow(){if(!vaultKey||current!=='vault')return vaultStart();const items=await vaultAll();if(!vaultKey||current!=='vault')return;
const counts=new Map();for(const x of items){const c=x.category||'Documents';counts.set(c,(counts.get(c)||0)+1)}
const cats=[...vaultCategoryDefaults.map(x=>x[0]),...Array.from(counts.keys()).filter(x=>!vaultCategoryDefaults.some(y=>y[0]===x))];
const inCategory=vaultCategoryView!==null;
const list=inCategory?items.filter(x=>(x.category||'Documents')===vaultCategoryView):[];
const tiles=cats.map(c=>`<button class="vault-category-tile" onclick="vaultSelectCategory(decodeURIComponent('${encodeURIComponent(c)}'))"><span class="vault-category-count">${counts.get(c)||0}</span><span class="vault-category-label">${vaultCategoryIcon(c)} ${esc(c)}</span></button>`).join('');
const cards=list.map(x=>`<div class="card stack"><strong>${esc(x.name)}</strong><small>${esc(x.category||'Documents')} · ${esc(x.date||'')} · ${(x.size/1024).toFixed(0)} Ko</small><div class="row" style="flex-wrap:wrap"><button class="btn" onclick="vaultPreview('${x.id}')">Consulter</button><button class="btn" onclick="vaultShare('${x.id}')">Télécharger</button><button class="btn" onclick="vaultRename('${x.id}')">Classer</button><button class="btn danger" onclick="vaultDelete('${x.id}')">Supprimer</button></div></div>`).join('');
$('#vaultScreen').innerHTML=`<div class="card stack vault-actions"><div class="row" style="justify-content:space-between"><h2 style="margin:0">🔐 Mes documents</h2><button class="btn" onclick="vaultLock();vaultStart()">Verrouiller</button></div><p class="muted">Stockage chiffré sur cet appareil · ${items.length} document(s)</p><label class="btn primary" style="text-align:center;cursor:pointer">＋ Importer un document<input type="file" multiple accept="application/pdf,image/*,.txt,.doc,.docx,.xlsx,.zip" style="display:none" onchange="vaultImport(this.files)"></label><button class="btn" onclick="vaultExport()">Exporter la sauvegarde chiffrée</button><label class="btn" style="text-align:center;cursor:pointer">Restaurer une sauvegarde<input type="file" accept="application/json,.json" style="display:none" onchange="vaultRestore(this.files[0])"></label></div>${inCategory?`<div class="stack"><button class="btn vault-category-back" onclick="vaultAllCategories()">← Toutes les catégories</button><h2>${vaultCategoryIcon(vaultCategoryView)} ${esc(vaultCategoryView)} (${list.length})</h2>${cards||'<div class="card muted">Aucun document dans cette catégorie.</div>'}</div>`:`<div class="vault-category-grid">${tiles}</div>`}`}

async function vaultImport(files){if(!vaultKey)return vaultStart();const key=vaultKey;for(const f of Array.from(files||[])){if(f.size>12*1024*1024){toast('Fichier trop volumineux (12 Mo maximum)');continue}try{const data=await vaultEncrypt(await f.arrayBuffer());if(vaultKey!==key)return;await vaultPut('files',{id:crypto.randomUUID(),name:f.name,type:f.type||'application/octet-stream',size:f.size,date:new Date().toLocaleDateString('fr-FR'),category:'Documents',...data})}catch(e){toast('Import impossible : stockage insuffisant ?');console.error(e)}}if(vaultKey)await vaultShow()}
async function vaultFile(id){const x=await vaultGet('files',id);if(!x)throw Error('Fichier introuvable');return {x,blob:new Blob([await vaultDecrypt(x)],{type:x.type})}}
function vaultSaveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function vaultPreview(id){try{const {x,blob}=await vaultFile(id);if(!/^(application\/pdf|image\/|text\/)/.test(x.type))return toast('Aperçu non disponible : télécharge le fichier');const url=URL.createObjectURL(blob);const win=window.open(url,'_blank');if(!win){vaultSaveBlob(blob,x.name);toast('Aperçu bloqué : fichier téléchargé')}setTimeout(()=>URL.revokeObjectURL(url),120000)}catch(e){toast('Aperçu impossible')}}
async function vaultRename(id){const x=await vaultGet('files',id);if(!x)return;const name=prompt('Nom du document',x.name);if(name===null)return;const category=prompt('Catégorie',x.category||'Documents');if(category===null)return;x.name=name.trim()||x.name;x.category=category.trim()||'Documents';await vaultPut('files',x);vaultCategoryView=x.category;vaultShow()}
async function vaultDownload(id){try{const {x,blob}=await vaultFile(id);vaultSaveBlob(blob,x.name)}catch(e){toast('Téléchargement impossible')}}
async function vaultShare(id){try{const {x,blob}=await vaultFile(id),file=new File([blob],x.name,{type:x.type});if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:x.name})}else{vaultSaveBlob(blob,x.name);toast('Fichier téléchargé : joins-le à ton mail depuis Fichiers')}}catch(e){if(e.name!=='AbortError')toast('Partage indisponible')}}
async function vaultDelete(id){if(!confirm('Supprimer définitivement ce document ?'))return;await vaultRemove(id);vaultShow()}
async function vaultExport(){try{const meta=await vaultGet('meta','config'),files=await vaultAll();vaultSaveBlob(new Blob([JSON.stringify({format:'nexo-vault',version:1,meta,files})],{type:'application/json'}),'nexo-coffre-chiffre-'+new Date().toISOString().slice(0,10)+'.json');toast('Sauvegarde chiffrée téléchargée')}catch(e){toast('Export impossible')}}
async function vaultRestore(file){if(!file)return;try{const backup=JSON.parse(await file.text());if(backup.format!=='nexo-vault'||backup.version!==1||!backup.meta?.pass||!backup.meta?.recovery||!Array.isArray(backup.files))throw Error('Format invalide');const existing=await vaultAll();if(existing.length||await vaultGet('meta','config')){if(!confirm('La restauration remplacera tout le coffre-fort actuel, y compris son mot de passe et sa clé de récupération. Continuer ?'))return}const db=await vaultDb();await new Promise((resolve,reject)=>{const tx=db.transaction(['meta','files'],'readwrite');tx.objectStore('meta').put(backup.meta,'config');tx.objectStore('files').clear();for(const item of backup.files){if(!item.id||!item.data||!item.iv)throw Error('Document invalide');tx.objectStore('files').put(item)}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();vaultLock();vaultStart();toast('Sauvegarde restaurée : déverrouille avec les anciens identifiants')}catch(e){toast('Sauvegarde invalide ou restauration impossible');console.error(e)}}
